fn encode(message: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(message.len());
    for c in message {
        match c {
            ' ' => {
                // Spaces stay as spaces
                result.push(' ');
            }
            // Vowels get mapped and then case‐swapped
            'a' => result.push('C'),
            'e' => result.push('G'),
            'i' => result.push('K'),
            'o' => result.push('Q'),
            'u' => result.push('W'),
            'A' => result.push('c'),
            'E' => result.push('g'),
            'I' => result.push('k'),
            'O' => result.push('q'),
            'U' => result.push('w'),
            // Consonants just get their case swapped
            other if other.is_ascii_alphabetic() => {
                if other.is_ascii_lowercase() {
                    result.push(other.to_ascii_uppercase());
                } else {
                    result.push(other.to_ascii_lowercase());
                }
            }
            // (By problem statement, no other characters can occur.)
            _ => unreachable!(),
        }
    }
    result
}

